"""Kalaratri `results.json` → markdown. Generated, never typed."""

from __future__ import annotations

import json
import sys


def main(path: str) -> int:
    with open(path, encoding="utf-8") as handle:
        r = json.load(handle)
    d = r["dataset"]
    s = d["split"]
    out = [
        "<!-- Generated by packages/sati/sati/loganomaly/report.py from the training workflow. Do not edit by hand. -->\n",
        "# Kalaratri v0 — log anomaly detection on real Hadoop logs\n",
        f"**{d['name']}** (Zenodo {d['zenodo_record']}): {d['blocks']:,} HDFS blocks, "
        f"{d['anomaly_share']:.2%} anomalous. Split **by time**: train {s['train']:,}, threshold on {s['validation']:,}, "
        f"test on the last {s['test']:,} — never shuffled. All three detectors scored on the same test blocks.\n",
        "| Detector | Precision | Recall | F1 | False-positive rate |",
        "|---|---:|---:|---:|---:|",
    ]
    for name, m in r["test"].items():
        label = "**Kalaratri v0**" if name.startswith("kalaratri") else name
        out.append(f"| {label} | {m['precision']:.3f} | {m['recall']:.3f} | {m['f1']:.3f} | {m['false_positive_rate']:.4f} |")
    out += [
        "",
        "## What it relies on\n",
        "| Feature | Gain |",
        "|---|---:|",
        *[f"| `{f['feature']}` | {f['gain']} |" for f in r["top_features"]],
        "",
        "## How to read this\n",
        "- Published HDFS results often split blocks at random and report F1 near 0.99; a time split is harder "
        "and closer to deployment, so lower numbers here are expected, not a regression.",
        f"- Weights are not published: {r['weights_note']}",
        "- Designed, written and trained by an AI assistant under the owner's direction "
        "([adr/RealDataModels](../../adr/RealDataModels.md)).",
    ]
    print("\n".join(out))
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1]))
